import clsx from 'clsx';
import React, { forwardRef, type ReactNode } from 'react';

import { buttonLabelCSS } from './Button.sty.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';

//#region Typings
/** Accepted properties for the Button Label */
export interface ButtonLabelProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the Button Label slot. */
  children: ReactNode;
}
//#endregion

/** Button Label component */
export const Label = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  ButtonLabelProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: ButtonLabelProps = props;

  const textual = _isStringChildren(children);

  return (
    <div
      ref={forwardedRef}
      data-testid={dataTestId}
      className={clsx(
        'strato-button-label',
        buttonLabelCSS({ textual }),
        consumerClassName,
      )}
      style={consumerStyle}
    >
      {children}
    </div>
  );
});

(Label as typeof Label & { displayName: string }).displayName = 'Button.Label';
